import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const root = new URL('../', import.meta.url);
const names = ['head', 'eye-left', 'eye-right', 'pupil-left', 'pupil-right', 'nostrils'];
const number = value => Number(value.toFixed(4));
const lines = [
  '// Generated by scripts/build-browser-mascot-paths.mjs from approved mascot contours.',
  "import 'dart:ui';", '',
  'abstract final class BrowserMascotPaths {',
];
for (const name of names) {
  const spec = JSON.parse(await readFile(new URL(`docs/assets/brand/motion/vector/${name}.json`, root), 'utf8'));
  const variable = name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  lines.push(`  static final ${variable} = Path()`);
  for (const shape of spec.shapes) {
    if (shape.type !== 'polygon') throw new Error(`Unexpected contour: ${name}`);
    for (const subpath of shape.subpaths) {
      const points = subpath.points;
      const xy = point => [number(point.x + shape.x), number(point.y + shape.y)];
      const handle = (point, incoming) => {
        const angle = (incoming ? point.cubic.inRotation : point.cubic.rotation) * Math.PI / 180;
        const distance = incoming ? point.cubic.inDistance : point.cubic.outDistance;
        return [number(point.x + shape.x + Math.cos(angle) * distance), number(point.y + shape.y + Math.sin(angle) * distance)];
      };
      lines.push(`    ..moveTo(${xy(points[0]).join(', ')})`);
      for (let i = 1; i < points.length; i++) {
        const previous = points[i - 1], current = points[i];
        if (previous.cubic && current.cubic) {
          lines.push(`    ..cubicTo(${[...handle(previous, false), ...handle(current, true), ...xy(current)].join(', ')})`);
        } else lines.push(`    ..lineTo(${xy(current).join(', ')})`);
      }
      lines.push('    ..close()');
    }
  }
  lines[lines.length - 1] += ';';
}
lines.push('}', '');
const target = new URL('clients/flutter/lib/src/features/browser/presentation/browser_mascot_paths.g.dart', root);
await writeFile(target, lines.join('\n'));
console.log(fileURLToPath(target));
